
(function(){
  function plain(h){var d=document.createElement('div');d.innerHTML=h;d.querySelectorAll('rt,rp').forEach(function(e){e.remove()});return (d.textContent||'').replace(/\s+/g,' ').trim();}
  function esc(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
  function build(){
    var lz=document.getElementById('lazy-news2'); if(!lz)return;
    if(!lz.textContent&&window.__loadTpls){try{window.__loadTpls();}catch(e){}}
    var tmp=document.createElement('div'); tmp.innerHTML=lz.textContent;
    var intro=tmp.querySelector('#news2-p1 .rn-intro'); if(!intro)return;
    var lines=intro.innerHTML.split(/<br\s*\/?>/i).map(plain).filter(function(t){return t.length>0;}).slice(0,3);
    var list=document.getElementById('tnList'); if(!list||!lines.length)return;
    list.innerHTML=lines.map(function(t){return '<button onclick="tnOpen()" style="display:block;width:100%;text-align:left;background:none;border:none;border-top:1px dashed #d8c9a3;padding:8px 2px;font-size:14px;line-height:1.5;cursor:pointer;color:inherit;">'+esc(t)+'</button>';}).join('');
  }
  window.tnOpen=function(){
    if(location.hash==='#news2'){ if(window.openCat)openCat('news2'); }
    else{ location.hash='news2'; }
    setTimeout(function(){var t=document.querySelector('.cat[data-cat="news2"]')||document.getElementById('news2'); if(t)t.scrollIntoView({behavior:'smooth',block:'start'});},450);
  };
  if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',build);}else{build();}
})();


