  function mtab(id,btn){
    document.querySelectorAll('.money-panel').forEach(p=>p.classList.remove('on'));
    document.getElementById('mp-'+id).classList.add('on');
    btn.parentElement.querySelectorAll('button').forEach(b=>b.classList.remove('on'));
    btn.classList.add('on');
    // バー再アニメ
    document.querySelectorAll('#mp-'+id+' .flow-fill').forEach(f=>{const w=f.dataset.w;f.style.width='0';setTimeout(()=>f.style.width=w+'%',50);});
    if(id==='gen'||id==='med'||id==='dist')drawGen();
  }
