  const RUBYSORTED=RUBYDIC.slice().sort((a,b)=>b[0].length-a[0].length);
  const RUBYMAP=Object.fromEntries(RUBYSORTED);
  const RUBYRE=new RegExp(RUBYSORTED.map(x=>x[0]).join('|'),'g');
  // 既存のruby内はスキップし、テキストノードだけにふりがなを付ける
  function rubyify(root){
    if(!root)return;
    if(root.closest&&root.closest('.no-ruby'))return;
    const skip=new Set(['SCRIPT','STYLE','RUBY','RT','BUTTON','HEADER','H1','NAV','SELECT','OPTION','OPTGROUP']);
    const skipCls=['no-ruby','nav','brand','money-tabs','logo','hero','hero-eyebrow','btns','furi-btn','site-head','head-inner'];
    const nodes=[];
    (function walk(n){
      if(n.nodeType===1){
        if(skip.has(n.tagName))return;
        if(n.classList&&skipCls.some(c=>n.classList.contains(c)))return;
        for(const c of Array.from(n.childNodes))walk(c);
      }else if(n.nodeType===3){
        if(/[\u4e00-\u9fff]/.test(n.textContent))nodes.push(n);
      }
    })(root);
    nodes.forEach(n=>{
      const html=n.textContent.replace(RUBYRE,k=>{
        let reading=RUBYMAP[k], word=k;
        // 送り仮名対応: 語末尾の連続ひらがなが読み末尾と一致するなら、その分をルビ対象から外す
        const tailKana=(word.match(/[ぁ-ん]+$/)||[''])[0];
        if(tailKana && reading.endsWith(tailKana)){
          const stem=word.slice(0,word.length-tailKana.length);      // 漢字部分
          const stemReading=reading.slice(0,reading.length-tailKana.length); // 漢字部分の読み
          if(stem && stemReading) return `<ruby>${stem}<rt>${stemReading}</rt></ruby>${tailKana}`;
        }
        return `<ruby>${word}<rt>${reading}</rt></ruby>`;
      });
      if(html!==n.textContent){
        const span=document.createElement('span');
        span.innerHTML=html;
        n.parentNode.replaceChild(span,n);
      }
    });
  }

  // ===== 用語グロス(タップでその場に解説) =====
  var GLOSS_MAP=null, GLOSS_RE=null, GLOSS_SEEN=null;
  function buildGloss(){
    if(GLOSS_MAP) return;
    GLOSS_MAP={};
    var T=window.GLOSS_TERMS||[];
    var stop={'パイ':1};
    var words=[];
    for(var i=0;i<T.length;i++){
      var t=T[i][0], yomi=T[i][1], desc=T[i][2];
      if(!t||stop[t]) continue;
      if(t.length<2) continue;
      if(!GLOSS_MAP[t]){ GLOSS_MAP[t]={y:yomi,d:desc}; words.push(t); }
    }
    words.sort(function(a,b){return b.length-a.length;});
    GLOSS_RE=words.map(function(w){return w.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}).join('|');
    GLOSS_SEEN={};
  }
  function glossify(root){
    if(!root) return;
    buildGloss();
    if(!GLOSS_RE) return;
    GLOSS_SEEN={};
    var reg=new RegExp(GLOSS_RE,'g');
    var skipTag={SCRIPT:1,STYLE:1,RT:1,BUTTON:1,SELECT:1,OPTION:1,H1:1,H2:1,SUMMARY:1};
    var skipCls={'no-ruby':1,'gloss':1,'money-tabs':1,'site-head':1};
    var nodes=[], rubies=[];
    (function walk(n){
      for(var c=n.firstChild;c;c=c.nextSibling){
        if(c.nodeType===1){
          if(skipTag[c.tagName]) continue;
          var cl=c.className&&c.className.split?c.className.split(' '):[];
          var sk=false; for(var q=0;q<cl.length;q++){ if(skipCls[cl[q]]){sk=true;break;} }
          if(sk) continue;
          if(c.tagName==='RUBY'){
            var grp=[c];
            while(true){
              var ns=c.nextSibling;
              if(ns && ns.nodeType===3 && ns.nodeValue.replace(/\s/g,'')==='' && ns.nextSibling && ns.nextSibling.nodeType===1 && ns.nextSibling.tagName==='RUBY'){ c=ns.nextSibling; grp.push(c); continue; }
              if(ns && ns.nodeType===1 && ns.tagName==='RUBY'){ c=ns; grp.push(c); continue; }
              break;
            }
            rubies.push(grp); continue;
          }
          walk(c);
        } else if(c.nodeType===3 && c.nodeValue && c.nodeValue.replace(/\s/g,'').length>1){
          nodes.push(c);
        }
      }
    })(root);
    for(var i=0;i<nodes.length;i++){
      var node=nodes[i], txt=node.nodeValue;
      reg.lastIndex=0;
      if(!reg.test(txt)) continue;
      reg.lastIndex=0;
      var frag=document.createDocumentFragment(), last=0, m;
      while((m=reg.exec(txt))){
        var w=m[0];
        var pv=txt.charAt(m.index-1), nx=txt.charAt(m.index+w.length);
        var kat=/[ァ-ヴー]/, kan=/[一-龯]/;
        if(kat.test(w.charAt(0))&&(kat.test(pv)||kat.test(nx))){ continue; }
        if(kan.test(w.charAt(0))&&kan.test(nx)){ continue; }
        if(m.index>last) frag.appendChild(document.createTextNode(txt.slice(last,m.index)));
        var span=document.createElement('span');
        span.className='gloss'; span.setAttribute('data-w',w); span.textContent=w;
        frag.appendChild(span);
        GLOSS_SEEN[w]=1;
        last=m.index+w.length;
      }
      if(last>0){
        if(last<txt.length) frag.appendChild(document.createTextNode(txt.slice(last)));
        if(node.parentNode) node.parentNode.replaceChild(frag,node);
      }
    }
    // ルビ済みの語: 連続するRUBYを連結して最長一致で照合(「普通」+「交付税」=「普通交付税」)
    for(var r=0;r<rubies.length;r++){
      var grp=rubies[r];
      var bases=[];
      for(var gi=0;gi<grp.length;gi++){
        var b='';
        for(var rc=grp[gi].firstChild;rc;rc=rc.nextSibling){
          if(rc.nodeType===3) b+=rc.nodeValue;
          else if(rc.nodeType===1 && rc.tagName!=='RT') b+=rc.textContent;
        }
        bases.push(b);
      }
      var used=[];
      for(var L=grp.length;L>=1;L--){
        for(var s0=0;s0+L<=grp.length;s0++){
          var clash=false;
          for(var q=s0;q<s0+L;q++){ if(used[q]){clash=true;break;} }
          if(clash) continue;
          var word=bases.slice(s0,s0+L).join('');
          if(GLOSS_MAP[word] && grp[s0].parentNode){
            var span=document.createElement('span');
            span.className='gloss'; span.setAttribute('data-w',word);
            grp[s0].parentNode.insertBefore(span,grp[s0]);
            var cur2=grp[s0], last2=grp[s0+L-1];
            while(cur2){ var nx2=cur2.nextSibling; span.appendChild(cur2); if(cur2===last2) break; cur2=nx2; }
            for(var q=s0;q<s0+L;q++){ used[q]=1; }
            GLOSS_SEEN[word]=1;
          }
        }
      }
    }
  }
  // タップで解説バブル
  document.addEventListener('click',function(e){
    var g=e.target.closest&&e.target.closest('.gloss');
    document.querySelectorAll('.gloss-pop').forEach(function(p){p.remove();});
    if(!g) return;
    e.stopPropagation();
    var w=g.getAttribute('data-w'), info=GLOSS_MAP&&GLOSS_MAP[w];
    if(!info) return;
    var pop=document.createElement('div');
    pop.className='gloss-pop';
    pop.innerHTML='<span class="gp-x">✕</span><b>'+w+(info.y?'（'+info.y+'）':'')+'</b><br>'+info.d;
    document.body.appendChild(pop);
    pop.querySelector('.gp-x').addEventListener('click',function(ev){ev.stopPropagation();pop.remove();});
  });


