  function _dayR(n){const S={1:'ついたち',2:'ふつか',3:'みっか',4:'よっか',5:'いつか',6:'むいか',7:'なのか',8:'ようか',9:'ここのか',10:'とおか',14:'じゅうよっか',20:'はつか',24:'にじゅうよっか'};return S[n]?`<ruby>${n}日<rp>(</rp><rt>${S[n]}</rt><rp>)</rp></ruby>`:`${n}<ruby>日<rp>(</rp><rt>にち</rt><rp>)</rp></ruby>`;}
  function renderToday(){
    const box=document.getElementById('todayBox');
    const dd=document.getElementById('todayDate');
    if(!box)return;
    const now=new Date(), m=now.getMonth()+1, d=now.getDate(), y=now.getFullYear();
    if(dd)dd.textContent=`${m}月${d}日`;
    let html='';
    const hits=DATED.filter(x=>x[0]===m&&x[1]===d).sort((a,b)=>b[2]-a[2]);
    if(hits.length){
      hits.forEach(x=>{
        const ago=y-x[2];
        const label = x[2]===0 ? `きょうは` : `${ago}<ruby>年前<rp>(</rp><rt>ねんまえ</rt><rp>)</rp></ruby>のきょう（${x[2]}<ruby>年<rp>(</rp><rt>ねん</rt><rp>)</rp></ruby>）`;
        html+=`<div class="insight" style="border-left-color:var(--gold);margin-top:8px;">
          <b style="color:var(--gold)">${label}</b><br>${x[3]}
          ${x[4]?`<div style="margin-top:6px;font-size:12px;color:var(--ink-soft);">💡 ${x[4]}</div>`:''}</div>`;
      });
    }else{
      const mo=DATED.filter(x=>x[0]===m).sort((a,b)=>a[1]-b[1]);
      // その年の通算日（1〜366）。これを使うと、リストを順ぐりに巡回でき、
      // 連続する日にちで同じ出来事が続けて出ることが決してない。
      const doy=Math.floor((now-new Date(y,0,0))/86400000);
      if(mo.length){
        const x=mo[doy%mo.length];
        html+=`<div class="insight blue" style="margin-top:8px;">
          <b><ruby>今月<rp>(</rp><rt>こんげつ</rt><rp>)</rp></ruby>のできごと：${x[0]}<ruby>月<rp>(</rp><rt>がつ</rt><rp>)</rp></ruby>${_dayR(x[1])}${x[2]===0?'':`（${x[2]}<ruby>年<rp>(</rp><rt>ねん</rt><rp>)</rp></ruby>）`}</b><br>${x[3]}
          ${x[4]?`<div style="margin-top:6px;font-size:12px;color:var(--ink-soft);">💡 ${x[4]}</div>`:''}</div>`;
      }
      const yv=YEARLY[doy%YEARLY.length];
      html+=`<div class="insight" style="border-left-color:var(--gold);margin-top:8px;">
        <b style="color:var(--gold)">${y-yv[0]}<ruby>年前<rp>(</rp><rt>ねんまえ</rt><rp>)</rp></ruby>の<ruby>今年<rp>(</rp><rt>ことし</rt><rp>)</rp></ruby>（${yv[0]}<ruby>年<rp>(</rp><rt>ねん</rt><rp>)</rp></ruby>）</b><br>${yv[1]}</div>`;
    }
    box.innerHTML=html;
    rubyify(box);
  }
  renderToday();

