  // ===== 用語フキダシ(2026-08-09): rubyifyより先に走らせる(ルビで語が分断される前にマッチさせるため) =====
  const TERMDIC={
   '経常収支比率':'毎年決まって入るお金のうち、人件費や借金返済など「必ず出ていくお金」が占める割合。100%に近いほど、自由に使えるお金がない=家計に余裕がない状態。',
   '債務負担行為':'「来年以降に払います」と議会で約束しておくお金のこと。今年の予算書には全額が出てこないが、将来の支払いは確定している。市役所版の「分割払いの契約」。',
   '実質公債費比率':'市の標準的な収入に対して、借金返済の負担がどれくらい重いかを示す割合。18%を超えると借金に国の許可が必要になり、25%を超えると黄信号(早期健全化基準)。',
   '将来負担比率':'市の標準的な収入(1年分)に対して、将来払うことになる借金や負担の合計がどれくらいあるかの割合。',
   '減価償却':'建物や道路が古くなって価値が減っていく分を、毎年の費用として数える会計の考え方。現金は出ていかないが、劣化は確実に進んでいる。',
   '普通会計':'全国の自治体を同じ物差しで比べるための決算の集計範囲。水道や市立病院などの企業会計は含まない。',
   '会計年度任用職員':'1年ごとの契約で働く自治体の非常勤職員。2020年度に始まった制度。',
   '政務活動費':'議員の調査研究などのために交付されるお金。使いみちの報告書は公開されている。',
   '指定管理':'市の施設の運営を、市が指定した企業・財団などに任せるしくみ。',
   '地方交付税':'どの自治体でも標準的な行政サービスができるように、国から配られる使いみち自由なお金。',
   '基金':'市の貯金。目的を決めて積み立てておき、必要なときに取り崩す。'
  };
  (function termify(){
    try{
      const keys=Object.keys(TERMDIC).sort((a,b)=>b.length-a.length);
      const re=new RegExp(keys.join('|'),'g');
      const skipTag={SCRIPT:1,STYLE:1,RUBY:1,RT:1,A:1,BUTTON:1,TEXTAREA:1,INPUT:1,SELECT:1,H1:1};
      const w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode:n=>{
        const p=n.parentElement; if(!p)return NodeFilter.FILTER_REJECT;
        if(skipTag[p.tagName])return NodeFilter.FILTER_REJECT;
        if(p.closest('#rinen,.no-ruby,#jiten,.term,a,button,svg'))return NodeFilter.FILTER_REJECT;
        re.lastIndex=0;
        return re.test(n.nodeValue)?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT;
      }});
      const targets=[]; while(w.nextNode())targets.push(w.currentNode);
      targets.forEach(n=>{
        const frag=document.createDocumentFragment(); let last=0; const s=n.nodeValue; re.lastIndex=0; let m;
        while((m=re.exec(s))){
          if(m.index>last)frag.appendChild(document.createTextNode(s.slice(last,m.index)));
          const sp=document.createElement('span'); sp.className='term'; sp.dataset.term=m[0]; sp.textContent=m[0];
          frag.appendChild(sp); last=m.index+m[0].length;
        }
        if(last<s.length)frag.appendChild(document.createTextNode(s.slice(last)));
        n.parentNode.replaceChild(frag,n);
      });
    }catch(e){}
  })();

