  // ===== コーナー・アコーディオン(4層構造の第1層) =====
  function initCornerFold(){
    const grid=document.querySelector('.cat-grid');
    if(!grid) return;
    const groups=[]; let cur=null;
    [...grid.children].forEach(el=>{
      if(el.classList.contains('catg')){cur={head:el,cards:[],open:false};groups.push(cur);}
      else if(cur&&el.classList.contains('cat')){cur.cards.push(el);}
    });
    if(groups.length<2) return;
    const OPEN_DEFAULT=['🎯','⚔️'];
    groups.forEach(g=>{
      const sp=g.head.querySelector('span');
      const label=sp?sp.textContent:'';
      const em=document.createElement('em'); em.className='catg-n'; em.textContent=g.cards.length+'枚';
      (sp||g.head).appendChild(em);
      g.set=(o)=>{g.open=o; g.cards.forEach(c=>c.classList.toggle('cfold-hide',!o)); g.head.classList.toggle('cg-open',o);};
      g.set(OPEN_DEFAULT.some(e=>label.indexOf(e)===0));
      g.head.addEventListener('click',()=>g.set(!g.open));
    });
    
  }
