  function openCat(id){
    const cur=document.querySelector('.cat-panel.on');
    const same=cur&&cur.id===id;
    document.querySelectorAll('.cat-panel').forEach(p=>p.classList.remove('on'));
    document.querySelectorAll('.cat').forEach(c=>c.classList.remove('on'));
    if(same){try{history.replaceState(null,'',location.pathname+location.search);}catch(e){}return;}
    const p=document.getElementById(id);
    if(!p)return;
    // パネルを対応カードの直下へ移動（カードがない場合は従来位置のまま）
    const tile=document.querySelector(`.cat[data-cat="${id}"]`);
    if(tile&&tile.parentNode&&tile.nextElementSibling!==p){tile.insertAdjacentElement('afterend',p);}
    window.__lastOpenedCat=id;
    if(!p.dataset.loaded){
      var lz=document.getElementById('lazy-'+id);
      if(lz){ p.insertAdjacentHTML('beforeend',lz.textContent); p.dataset.loaded='1';
        if(window.__cardInit&&window.__cardInit[id]){try{window.__cardInit[id]();}catch(e){}}
        var __LR={kouyaku:'kouyakuRender',sanpi:'sanpiRender'};
        if(__LR[id]&&window[__LR[id]]){try{window[__LR[id]]();}catch(e){}}
        if(id==='kouka'){try{window.initKohka&&initKohka();}catch(e){}try{window.showKohka&&showKohka();}catch(e){}}
        if(window.rubyify){try{rubyify(p);}catch(e){}}
      }
    }
    p.classList.add('on');
    if(!p.dataset.glossed){p.dataset.glossed='1';setTimeout(function(){try{glossify(p);}catch(e){}},250);}
    try{history.replaceState(null,'','#'+id);}catch(e){}
    if(id==='quiz100' && typeof qzInit==='function'){ try{ qzInit(); }catch(e){} }
    if(id==='power' && typeof subsidyInit==='function'){ try{ subsidyInit(); }catch(e){} }
    document.querySelector(`.cat[data-cat="${id}"]`)?.classList.add('on');
    // レンダー系を必要に応じて呼ぶ
    setTimeout(()=>{
      p.scrollIntoView({block:'start'});
    },60);
  }
