  // 給与所得控除（2026年・最低保障74万円）
  function kyuyoDeduction(income){
    let kj;
    if(income<=1900000)kj=Math.max(740000,income*0.4-100000);
    else if(income<=3600000)kj=income*0.3+80000;
    else if(income<=6600000)kj=income*0.2+440000;
    else if(income<=8500000)kj=income*0.1+1100000;
    else kj=1950000;
    if(income<=1625000)kj=Math.min(kj,Math.max(740000,income));
    return Math.min(income,kj);
  }
  // 所得税の基礎控除（2026年・令和8年分：合計所得655万円以下は104万円＝本則62万＋特例42万）
  function kisoIncomeTax(goukeiShotoku){
    if(goukeiShotoku<=6550000)return 1040000;  // 62万＋特例42万（令和8・9年分）
    if(goukeiShotoku<=23500000)return 620000;  // 本則62万
    if(goukeiShotoku<=24000000)return 480000;
    if(goukeiShotoku<=24500000)return 320000;
    if(goukeiShotoku<=25000000)return 160000;
    return 0;
  }

  function calc(){
    const man0=Math.max(0,parseFloat(document.getElementById('incomeMan').value)||0);
    const income=man0*10000;
    const k0=Math.max(0,parseInt(document.getElementById('k0').value)||0);
    const k3=Math.max(0,parseInt(document.getElementById('k3').value)||0);
    const k16=Math.max(0,parseInt(document.getElementById('k16').value)||0);
    const k19=Math.max(0,parseInt(document.getElementById('k19').value)||0);
    const kidsAll=k0+k3+k16+k19;
    const isSelf=state.job==='self';
    const isPart=state.job==='parttime';
    const isO40=state.age==='o40';

    // 配偶者：年収→合計所得を出し、控除の可否を判定（2026年：給与収入136万以下で配偶者控除）
    let spouseIncome=0,spouseHasControl=false,spouseSpecial=0;
    if(state.spouse==='yes'){
      spouseIncome=(parseFloat(document.getElementById('spouseMan').value)||0)*10000;
      const spShotoku=Math.max(0,spouseIncome-kyuyoDeduction(spouseIncome));
      if(spShotoku<=620000){spouseHasControl=true;} // 配偶者控除（38万/住民33万）
      else if(spouseIncome<=1690000){spouseSpecial=2;} // 配偶者特別控除・満額38万（給与収入169万以下）
      else if(spouseIncome<=2070000){spouseSpecial=1;} // 配偶者特別控除・段階縮小ゾーン（概算で半額）
      // ヒント表示
      const hint=document.getElementById('spouseHint');
      if(spouseIncome===0)hint.textContent='';
      else if(spouseIncome<=1300000)hint.textContent='配偶者は扶養の範囲内（社会保険料の負担なし）とみられます。';
      else hint.textContent='配偶者は自分で社会保険に入る収入額とみられます。';
    }

    // 本人の給与所得 or 事業所得
    let shotoku;
    if(isSelf)shotoku=Math.max(0,income*0.6);
    else shotoku=Math.max(0,income-kyuyoDeduction(income));

    // 社会保険料
    let kenko=0,nenkin=0,koyo=0,kaigo=0,shakai=0,hokenNote='';
    if(isSelf){
      kenko=income>0?Math.min(920000,Math.round(Math.max(0,shotoku-430000)*0.11+50000)):0; // 国保（医療+支援分・賦課限度額あり）
      nenkin=income>0?215040:0; // 国民年金 令和8年度 月17,920円
      if(isO40)kaigo=Math.min(170000,Math.round(Math.max(0,shotoku-430000)*0.02));
      shakai=kenko+nenkin+kaigo;
    }else if(isPart&&income<1300000){
      shakai=0;hokenNote='年収130万円未満のため、健康保険・年金の本人負担はありません（扶養の範囲内）。ただし週20時間以上働く場合は雇用保険（給与の0.55%）がかかり、大きな会社（51人以上）では約106万円から社会保険に入る場合があります（この壁は2026年10月に撤廃予定）。';
    }else{
      // 標準報酬月額の上限：健康保険 月139万/厚生年金 月65万
      kenko=Math.round(Math.min(income,16680000)*0.05);
      nenkin=Math.round(Math.min(income,7800000)*0.0915);
      koyo=Math.round(income*0.0055);
      if(isO40)kaigo=Math.round(Math.min(income,16680000)*0.009);
      shakai=kenko+nenkin+koyo+kaigo;
      if(isPart)hokenNote='年収130万円以上のため、自分で社会保険に入ります。そのぶん将来の年金は増えます。';
    }

    // --- 所得税 ---
    const kiso=kisoIncomeTax(shotoku);
    const spouseDedIncome=spouseHasControl?380000:(spouseSpecial===2?380000:(spouseSpecial===1?190000:0));
    const kidsDedIncome=k16*380000+k19*630000; // 一般扶養38万＋特定扶養63万
    let t=Math.max(0,shotoku-shakai-kiso-spouseDedIncome-kidsDedIncome);
    t=Math.floor(t/1000)*1000;
    let it=0;
    if(t<=1950000)it=t*0.05;else if(t<=3300000)it=t*0.10-97500;else if(t<=6950000)it=t*0.20-427500;
    else if(t<=9000000)it=t*0.23-636000;else if(t<=18000000)it=t*0.33-1536000;else if(t<=40000000)it=t*0.40-2796000;else it=t*0.45-4796000;
    it=Math.max(0,Math.floor(it*1.021)); // 復興特別所得税

    // --- 住民税（金沢市：所得割10%＝市6%＋県4%、均等割4,500円＋森林環境税1,000円、基礎控除43万）---
    const kisoRes=430000;
    const spouseDedRes=spouseHasControl?330000:(spouseSpecial===2?330000:(spouseSpecial===1?165000:0));
    const kidsDedRes=k16*330000+k19*450000; // 一般33万＋特定45万
    let r=Math.max(0,shotoku-shakai-kisoRes-spouseDedRes-kidsDedRes);
    r=Math.floor(r/1000)*1000;
    // 非課税判定（金沢市：均等割も所得割もかからない線＝単身は合計所得42万円以下、扶養ありは32万×人数＋29万。金沢市公式「市・県民税が課税されない方」による）
    const famN=1+(spouseHasControl?1:0)+kidsAll; // 非課税判定は16歳未満の子も人数に含む
    const hikazeiLimit=(famN>1)?(famN*320000+290000):420000;
    const hasTax=shotoku>hikazeiLimit;
    // 調整控除（人的控除差の調整・標準的に2,500円＝市1,500円＋県1,000円）
    const chosei=hasTax&&r>0?2500:0;
    let jumin=hasTax?Math.max(0,Math.round(r*0.10)-chosei)+5500:0;
    const cityShare=hasTax?Math.max(0,Math.round(r*0.06)-(chosei?1500:0))+3000:0; // 金沢市ぶん（市民税6%－調整控除市分＋均等割3,000円）

    const totalPay=shakai+it+jumin;
    const tedori=income-totalPay;
    const pct=income>0?Math.round(tedori/income*100):0;
    const P=(v)=>income>0?('（'+(Math.round(v/income*1000)/10)+'%）'):'';

    document.getElementById('tedori').textContent=income>0?yen(tedori):'－';
    document.getElementById('paidAmt').textContent=income>0?(yen(totalPay)+'（'+Math.round(totalPay/income*100)+'%）'):'－';
    document.getElementById('tedoriSub').textContent=income>0?('1年の収入の約'+pct+'％。1か月あたり約'+yen(tedori/12)):'';

    // 内訳（ふりがな入り・割合つき）
    const R=(txt,rt)=>''+txt+'';
    const rows=[];
    if(income>0){
      rows.push(['head', R('控除','こうじょ')+'される<ruby>金額<rp>(</rp><rt>きんがく</rt><rp>)</rp></ruby>（<ruby>税金<rp>(</rp><rt>ぜいきん</rt><rp>)</rp></ruby>がかからない<ruby>部分<rp>(</rp><rt>ぶぶん</rt><rp>)</rp></ruby>）','','','h-ded']);
      if(isSelf){
        rows.push(['', R('経費','けいひ')+'みなし'+R('分','ぶん'),'この試算では収入の4割と仮定',income-shotoku,'r-ded']);
      }else if(income-shotoku>0){
        rows.push(['', R('給与所得控除','きゅうよしょとくこうじょ'),'会社員の経費みなし分',income-shotoku,'r-ded']);
      }
      rows.push(['', R('社会保険料控除','しゃかいほけんりょうこうじょ'),'下で払う保険料はそのまま全額',shakai,'r-ded']);
      rows.push(['', R('基礎控除','きそこうじょ'),'だれでも引ける基本の控除。住民税の計算では'+man(kisoRes),kiso,'r-ded']);
      if(spouseDedIncome>0)rows.push(['', R('配偶者控除','はいぐうしゃこうじょ'),'住民税の計算では'+man(spouseDedRes),spouseDedIncome,'r-ded']);
      if(kidsDedIncome>0)rows.push(['', R('扶養控除','ふようこうじょ'),'16歳以上の子など。住民税の計算では'+man(kidsDedRes),kidsDedIncome,'r-ded']);
    }
    rows.push(['head', R('納','おさ')+'めるもの（あなたが<ruby>払<rp>(</rp><rt>はら</rt><rp>)</rp></ruby>うお<ruby>金<rp>(</rp><rt>かね</rt><rp>)</rp></ruby>）','','','h-pay']);
    if(isSelf){
      rows.push(['', R('国民健康保険料','こくみんけんこうほけんりょう'),'医療などのための保険',kenko,'r-pay']);
      rows.push(['', R('国民年金','こくみんねんきん'),'老後などのための年金',nenkin,'r-pay']);
      if(kaigo)rows.push(['', R('介護保険料','かいごほけんりょう'),'40歳以上',kaigo,'r-pay']);
    }else if(isPart&&income<1300000){
      rows.push(['note', R('社会保険料','しゃかいほけんりょう'),'扶養の範囲内のため本人負担なし','0円','r-pay']);
    }else{
      rows.push(['', R('健康保険料','けんこうほけんりょう'),'医療などのための保険',kenko,'r-pay']);
      rows.push(['', R('厚生年金保険料','こうせいねんきんほけんりょう'),'老後などのための年金',nenkin,'r-pay']);
      rows.push(['', R('雇用保険料','こようほけんりょう'),'失業などにそなえる保険',koyo,'r-pay']);
      if(kaigo)rows.push(['', R('介護保険料','かいごほけんりょう'),'40歳以上',kaigo,'r-pay']);
    }
    rows.push(['', R('所得税','しょとくぜい'),(it>0?('国に納める税金。上の青い控除を引いた残り＝課税所得'+man(t)+'にかかる'):'今の条件では課税所得が0円のため、かかりません'),it,'r-pay']);
    rows.push(['', R('住民税','じゅうみんぜい'),(hasTax?('石川県と金沢市に納める税金。課税所得'+man(r)+'×10%−調整控除2,500円＋均等割4,500円＋森林環境税1,000円'):'今の条件では非課税です'),jumin,'r-pay']);
    rows.push(['sum', R('納','おさ')+'める'+R('合計','ごうけい'),'',totalPay,'']);
    let html='';
    rows.forEach(x=>{
      const cls=((x[0]==='head'?'head ':x[0]==='sum'?'sum ':'')+(x[4]||'')).trim();
      const tr='<tr'+(cls?(' class="'+cls+'"'):'')+'>';
      if(x[0]==='head'){html+=tr+'<td colspan="3">'+x[1]+'</td></tr>';return;}
      if(x[0]==='sum'){html+=tr+'<td class="l">'+x[1]+'</td><td class="r">'+yen(x[3])+'</td><td class="r" style="width:64px;color:var(--red)">'+P(x[3])+'</td></tr>';return;}
      if(x[0]==='note'){html+=tr+'<td class="l">'+x[1]+'<small>'+x[2]+'</small></td><td class="r">'+x[3]+'</td><td></td></tr>';return;}
      const s=x[2]?'<small>'+x[2]+'</small>':'';
      html+=tr+'<td class="l">'+x[1]+s+'</td><td class="r">'+(x[3]!==''?yen(x[3]):'')+'</td><td class="r" style="width:64px;color:#a49a86;">'+(x[3]?P(x[3]):'')+'</td></tr>';
    });
    if(hokenNote)html+='<tr><td colspan="3" style="font-size:11px;color:var(--green);padding-top:10px;">💡 '+hokenNote+'</td></tr>';
    document.getElementById('bd').innerHTML=html;

    // 金沢にとどくお金
    document.getElementById('tkAmt').textContent=income>0?yen(cityShare):'－';
    document.getElementById('tkDesc').textContent=
      cityShare>0?('あなたが納める税金のうち、住民税の「市民税」ぶん（約'+man(cityShare)+'／全体の'+(Math.round(cityShare/income*1000)/10)+'%）が、金沢市に直接とどきます。それはたとえば、こんなことに使われています：')
      :(income>0?'いまの年収では、金沢市に納める住民税（市民税）はかかりません。':'');
    let ul='';
    if(cityShare>0){
      USE.forEach(u=>{
        const amt=Math.round(cityShare*u[2]);
        ul+='<div class="use-row"><div class="ul-lab"><span>'+u[0]+'　<b style="font-weight:500;color:var(--ink-soft)">'+u[1]+'</b></span><b>'+yen(amt)+'</b></div><div class="use-track"><div class="use-fill" style="width:'+(u[2]*100)+'%;background:'+u[3]+'"></div></div></div>';
      });
    }
    document.getElementById('useList').innerHTML=ul;

    // ===== もらえるお金（児童手当・2024年10月拡充後）=====
    // 上の子から数える：19-22歳→16-18歳→3-15歳→0-2歳。第3子以降は月3万。19-22歳はカウントのみ（支給なし）
    let jidoMonthly=0;const rcItems=[];
    let pos=k19; // 19-22歳が上位を占める（支給なし）
    let m16=0;for(let i=0;i<k16;i++){pos++;m16+=(pos>=3?30000:10000);}
    let m3=0;for(let i=0;i<k3;i++){pos++;m3+=(pos>=3?30000:10000);}
    let m0=0;for(let i=0;i<k0;i++){pos++;m0+=(pos>=3?30000:15000);}
    jidoMonthly=m16+m3+m0;
    const jidoYear=jidoMonthly*12;
    const rb=document.getElementById('receiveBox');
    if(jidoYear>0){
      rb.style.display='block';
      document.getElementById('rcAmt').textContent='年 '+yen(jidoYear);
      let d='';
      if(m0>0)d+='<div class="rc-detail">0〜2歳（'+k0+'人）：月 '+yen(m0)+'（1人あたり月1.5万円、第3子以降は月3万円）</div>';
      if(m3>0)d+='<div class="rc-detail">3〜15歳（'+k3+'人）：月 '+yen(m3)+'（1人あたり月1万円、第3子以降は月3万円）</div>';
      if(m16>0)d+='<div class="rc-detail">16〜18歳（'+k16+'人）：月 '+yen(m16)+'（高校生年代も2024年10月から対象に）</div>';
      if(k19>0)d+='<div class="rc-detail">19〜22歳（'+k19+'人）：支給はありませんが「第3子」の数えかたに含まれ、下の子の手当が増えます</div>';
      document.getElementById('rcDetail').innerHTML=d;
      document.getElementById('rcNet').innerHTML='手取りとあわせると、1年で実質 <span style="font-size:16px;">'+yen(tedori+jidoYear)+'</span> が家庭に入ります。';
    }else{
      rb.style.display=(kidsAll>0)?'block':'none';
      if(kidsAll>0){
        document.getElementById('rcAmt').textContent='年 0円';
        document.getElementById('rcDetail').innerHTML='<div class="rc-detail">19〜22歳のお子さんは児童手当の支給対象外です（高校生年代までが対象）。</div>';
        document.getElementById('rcNet').innerHTML='';
      }
    }

    // ===== あなた専用の解説 =====
    const W=[];
    const kyuyo=isSelf?0:kyuyoDeduction(income);
    if(income===0){
      W.push('年収を入力すると、あなたに合わせた説明が出ます。');
    }else{
      if(isSelf){
        W.push('<b>自営業・フリーランス</b>のため、会社員の「給与所得控除」はありません。かわりに実際の経費を引いて所得を計算します（ここでは収入の約6割を所得と仮定）。健康保険は国民健康保険、年金は国民年金になります。');
      }else{
        W.push('働く人には、経費代わりの「<b>給与所得控除 '+man(kyuyo)+'</b>」が自動で引かれています。');
      }
      // 所得税の壁（実際の計算結果に基づいて説明する）
      if(!isSelf){
        if(it===0&&income>0){
          if(shakai>0){
            W.push('あなたの<b>所得税は0円</b>です。「178万の壁」（基礎控除104万＋給与所得控除74万）に加え、払った社会保険料（'+man(shakai)+'）も<b>全額控除</b>になるため、実際に所得税がかかり始めるのは「178万＋社会保険料のぶん」（社会保険に入っている人なら目安約204万）からです。');
          }else{
            const nokori=1780000-income;
            W.push('あなたの年収は<span class="wall">「178万の壁」より下</span>。基礎控除＋給与所得控除でカバーされ、<b>所得税は0円</b>です。'+(nokori>0?('あと<b>'+man(nokori)+'</b>ふえると、所得税がかかり始めます。'):''));
          }
        }else if(it>0){
          W.push('控除（基礎控除'+man(kiso)+'・給与所得控除・社会保険料など）を引いた残り<b>'+man(t)+'</b>に所得税がかかっています。基礎控除は合計所得655万をこえると段階的に小さくなります。');
        }
      }
      // 社会保険の壁（パート）
      if(isPart){
        if(income<1300000){
          const nokori=1300000-income;
          W.push('パート・アルバイトで<span class="wall">「130万の壁」より下</span>なので、<b>社会保険料の負担は0円</b>（家族の扶養の中）。ただし、あと<b>'+man(nokori)+'</b>ふえて130万をこえると、自分で社会保険に入るため、一時的に手取りが減ることがあります（働き方の注意点）。');
        }else{
          W.push('年収130万をこえたので、家族の扶養から外れ、<b>自分で社会保険料を払</b>っています。そのぶん将来の年金は増えます。');
        }
      }
      // 配偶者
      if(state.spouse==='yes'){
        if(spouseHasControl){
          W.push('配偶者の年収が<b>136万以下</b>なので、あなたは<b>配偶者控除</b>（所得税38万／住民税33万）が受けられ、そのぶん税金が安くなっています。');
        }else if(spouseSpecial){
          W.push('配偶者の年収が136万をこえたため配偶者控除の満額ではありませんが、<b>配偶者特別控除</b>が段階的に受けられます（いきなりゼロにならない仕組み）。');
        }else{
          W.push('配偶者の年収が高めのため、配偶者による控除はありません（それぞれが自分の収入に応じて納税）。');
        }
      }
      // 子ども
      if(k16>0){
        W.push('16〜18歳のお子さん<b>'+k16+'人</b>ぶんの「扶養控除」（1人あたり所得税38万／住民税33万）が引かれています。しかも2024年10月から児童手当も高校生年代まで延長され、<b>控除と手当の両方</b>が受けられます。');
      }
      if(k19>0){
        W.push('19〜22歳のお子さん<b>'+k19+'人</b>ぶんは「特定扶養控除」（1人あたり所得税63万／住民税45万）。大学などでお金がかかる年代なので、控除がいちばん大きくなっています。');
      }
      if(k0+k3>0){
        W.push('15歳以下のお子さん<b>'+(k0+k3)+'人</b>には税金の控除はありません。2010年に「控除から手当へ」の方針で廃止され、かわりに<b>児童手当を現金で受け取る</b>形になっています（下の緑の枠）。収入が高い人ほど得する控除より、全員同じ額の現金のほうが公平、という考え方です。');
      }
      // 介護保険
      if(isO40){
        W.push('40歳以上のため、健康保険に<b>介護保険料</b>が上乗せされています。');
      }
      // 住民税
      if(hasTax){
        W.push('住民税は金沢市で<b>課税所得の10%＋均等割4,500円＋森林環境税1,000円</b>（市民税6%＋県民税4%）。このうち市民税ぶんが、金沢市に直接とどきます。');
        W.push('<b>「10%」は年収まるごとにはかかりません。</b>'+'年収'+man(income)+' − '+(isSelf?('経費みなし分 '+man(income-shotoku)+'（この試算では収入の4割と仮定）'):('給与所得控除 '+man(income-shotoku)+'（会社員の経費みなし分）'))+' − 社会保険料控除 '+man(shakai)+' − 基礎控除 43万円'+((spouseDedRes+kidsDedRes)>0?(' − 配偶者・扶養の控除 '+man(spouseDedRes+kidsDedRes)):'')+' ＝ <b>課税所得 約'+man(r)+'</b>。10%がかかるのはここ。だから年収に対する実際の割合（上の表の％）は10%より低くなります。');
        W.push('<b>「実質の負担は40%超」と聞いたことがあるかも。</b>それは国の「国民負担率」＝国全体の税金と社会保険料の合計を国民所得で割ったもので、令和7年度は46%前後（財務省）。ただし分母も中身もこの表とは別モノです。この表はあなたの給与明細に出る<b>本人負担だけ</b>。実は会社側も、あなたの社会保険料とほぼ同じ額を別に負担しています（明細には出ません）。さらに買い物のたびの消費税もある。そこまで足し込むと、実感の負担は表の％よりずっと重くなります。');
      }else{
        W.push('いまの条件では、住民税は<b>まるごと非課税</b>（0円）です。住民税には「<b>非課税限度額</b>」という線引きがあり、金沢市では'+(famN>1?'<b>所得32万円×家族の人数＋29万円</b>':'<b>所得42万円</b>')+'以下なら、均等割4,500円＋森林環境税1,000円もふくめて全額かかりません。あなたの場合：家族'+famN+'人 → ライン'+man(hikazeiLimit)+'、所得（収入から'+(isSelf?'経費みなし分':'給与所得控除')+'を引いた額）は'+man(shotoku)+'。なお、<b>扶養控除のない16歳未満の子どもも「人数」には数えます</b>。子どもが増えると基準額が1人につき32万円ずつ上がり、所得が基準額以下になると住民税は全額かかりません。基準額を1円でも超えると全額かかる、段階のないしくみです。');
      }
    }
    document.getElementById('whyList').innerHTML=W.map(w=>'<li>'+w+'</li>').join('');
    // 計算結果の説明文にふりがなを付与（数字表示は除く）
    ['bd','whyList','useList'].forEach(id=>rubyify(document.getElementById(id)));
    const tkd=document.getElementById('tkDesc'); if(tkd)rubyify(tkd);
  }

