  const KOYUC={"jin": "👤 人物", "jis": "⛩️ 寺社", "shi": "🏯 城・史跡", "mac": "🗺️ 町・地名", "koh": "🏘️ 校下", "sch": "🏫 学校", "miz": "🌊 川・用水・山", "sak": "🪧 坂・橋", "ses": "🏛️ 施設", "ka": "🏢 市役所の課", "gyo": "🎆 祭り・行事", "mon": "🏺 工芸・食", "rek": "📜 歴史・交通", "sei": "🏛 政治・団体", "kei": "📋 計画・条例"};
  let jitenM='kotoba';
  let koyuG='all';
  let jitenG='all';
  function _plainR(s){return String(s).replace(/<rp>[^<]*<\/rp>|<rt>[^<]*<\/rt>/g,'').replace(/<[^>]+>/g,'');}
  function _rubyT(t,y){try{if(!y||!/[一-鿿々]/.test(t))return t;const k2h=s=>s.replace(/[ァ-ヶ]/g,c=>String.fromCharCode(c.charCodeAt(0)-96));const segs=t.match(/[一-鿿々〆ヶ]+|[^一-鿿々〆ヶ]+/g);const esc=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');const re=new RegExp('^'+segs.map(s=>/[一-鿿々〆ヶ]/.test(s)?'(.+?)':'('+esc(k2h(s))+')').join('')+'$');const m=y.match(re);if(!m)return t;return segs.map((s,i)=>/[一-鿿々〆ヶ]/.test(s)?`<ruby>${s}<rp>(</rp><rt>${m[i+1]}</rt><rp>)</rp></ruby>`:s).join('');}catch(e){return t;}}
  function jitenRender(){
    const grid=document.getElementById('jgrid');
    if(!grid)return;
    const a=JITEN.map((x)=>{
      const [g,t,y,s,d]=x; const sc=JSC[s];
      return `<details class="jgo" data-m="kotoba" data-g="${g}" data-s="${(t+' '+y+' '+_plainR(d)).toLowerCase()}"><summary><span class="jt">${_rubyT(t,y)}</span><span class="scope ${sc[1]}">${sc[0]}</span></summary><div class="jbody">${d}</div></details>`;
    }).join('');
    const b=KOYU.map((x)=>{
      const [g,t,y,d]=x;
      return `<details class="jgo" data-m="koyu" data-g="${g}" data-s="${(t+' '+y+' '+_plainR(d)).toLowerCase()}"><summary><span class="jt">${t}</span><span class="scope kz">${KOYUC[g].replace(/^\S+\s/,'')}</span></summary><div class="jbody">${y?'<span style="font-size:12px;color:var(--ink-soft)">（'+y+'）</span><br>':''}${d}</div></details>`;
    }).join('');
    grid.innerHTML=a+b+'<div class="jempty" id="jempty" style="display:none">見つかりませんでした。ちがうことばで、さがしてみてください。</div>';
    rubyify(grid);
    jitenApply();
  }
  function jitenMode(btn){
    document.querySelectorAll('#jmode .jtab').forEach(b=>b.classList.remove('on'));
    btn.classList.add('on');
    jitenM=btn.dataset.m;
    document.getElementById('jtabs-kotoba').style.display=jitenM==='kotoba'?'':'none';
    document.getElementById('jtabs-koyu').style.display=jitenM==='koyu'?'':'none';
    const lg=document.querySelector('#jiten .jlegend'); if(lg)lg.style.display=jitenM==='kotoba'?'':'none';
    const jq=document.getElementById('jq'); if(jq)jq.placeholder=jitenM==='kotoba'?'ことばをさがす（例：GDP、消費税、条例）':'名前をさがす（例：犀川、暗がり坂、利家、長田町）';
    jitenApply();
  }
  function koyuTab(btn){
    document.querySelectorAll('#jtabs-koyu .jtab').forEach(b=>b.classList.remove('on'));
    btn.classList.add('on');
    koyuG=btn.dataset.g;
    jitenApply();
  }
  function jitenTab(btn){
    document.querySelectorAll('.jtab').forEach(b=>b.classList.remove('on'));
    btn.classList.add('on');
    jitenG=btn.dataset.g;
    jitenApply();
  }
  function jitenApply(){
    const q=(document.getElementById('jq')?.value||'').trim().toLowerCase();
    let n=0;
    document.querySelectorAll('#jgrid .jgo').forEach(el=>{
      const g=el.dataset.m==='kotoba'?jitenG:koyuG;
      const ok=el.dataset.m===jitenM&&(g==='all'||el.dataset.g===g)&&(!q||el.dataset.s.includes(q));
      el.style.display=ok?'':'none';
      if(ok)n++;
    });
    const c=document.getElementById('jcount');
    const total=jitenM==='kotoba'?JITEN.length:KOYU.length;
    const g=jitenM==='kotoba'?jitenG:koyuG;
    if(c)c.textContent=(q||g!=='all')?n+'語を表示中':'全'+total+'語';
    const em=document.getElementById('jempty');
    if(em)em.style.display=n===0?'block':'none';
  }
  // ===== 追加セクション（データ・まつり・文化・安全） =====
  function ptab(sec,id,btn){
    document.querySelectorAll('#'+sec+' .money-panel').forEach(p=>p.classList.remove('on'));
    document.getElementById(sec+'-'+id).classList.add('on');
    btn.parentElement.querySelectorAll('button').forEach(b=>b.classList.remove('on'));
    btn.classList.add('on');
  }
