  const KAIHA=['自民','みらい','市民目線','公明','共産','創生','さくら','結び'];
  function sanpiRender(){
    const g=document.getElementById('sanpiGrid');
    if(!g)return;
    g.innerHTML=SANPI.map(x=>{
      const chips=x.v.map((v,i)=>{
        if(v==='o')return `<span class="vchip vo">${KAIHA[i]} ◯</span>`;
        if(v==='x')return `<span class="vchip vx">${KAIHA[i]} ×</span>`;
        const [a,b]=v.slice(1).split('_');
        return `<span class="vchip vd">${KAIHA[i]} △ ${a}/${b}人賛成</span>`;
      }).join('');
      return `<details class="jgo"><summary><span class="jt">${x.t}</span><span class="rslt ${x.pass?'pass':'fail'}">${x.r}</span></summary><div class="jbody"><div class="vchips">${chips}</div>${x.e}${x.n?`<div class="vnote">📝 ${x.n}</div>`:''}</div></details>`;
    }).join('');
    rubyify(g);
  }
