// --- ゲーム開始 ---
function qzStartGame(practice){
  QZ_practice = practice;
  QZ_idx = 0; QZ_score = 0; QZ_correct = 0; QZ_results = [];
  // 今日の10問を決める（練習モードはランダム、本番は日付シード）
  if(practice){
    // 練習：全問を通しで（ランダム順・全問マスター用）
    QZ_today = qzShuffle(QUIZ100);
  }else{
    // 本番：全問一巡モード。日替わりで10問ずつ、抜け・ダブりなく全問を巡回する
    const order = qzShuffle(QUIZ100, qzRng(20260101));
    const blocks = Math.ceil(order.length/10);
    const epoch = Date.UTC(2026,0,1);
    const t = new Date();
    const dayIndex = Math.floor((Date.UTC(t.getFullYear(),t.getMonth(),t.getDate()) - epoch)/86400000);
    const block = ((dayIndex % blocks) + blocks) % blocks;
    QZ_today = order.slice(block*10, block*10+10);
  }
  qzRenderQuestion();
}

// --- 問題表示 ---
function qzRenderQuestion(){
  const box = document.getElementById('qzBody');
  const q = QZ_today[QZ_idx];
  QZ_answered = false;
  // 3択をランダムシャッフル（正解位置も毎回変わる）
  const opts = q.c.map((text,i)=>({text, correct:i===q.a}));
  const shuffled = qzShuffle(opts);
  q._shuffled = shuffled;
  box.innerHTML =
    '<div class="qz-play">'+
    '<div class="qz-progress"><span>第 '+(QZ_idx+1)+' 問 / '+QZ_today.length+'問</span>'+
      '<span class="qz-cat">'+q.cat+'</span>'+
      '<span class="qz-timer" id="qzTimer">0.0秒</span></div>'+
    '<div class="qz-bar"><div class="qz-bar-fill" style="width:'+((QZ_idx)/QZ_today.length*100)+'%"></div></div>'+
    '<div class="qz-question">'+q.q+'</div>'+
    '<div class="qz-opts" id="qzOpts">'+
      shuffled.map((o,i)=>'<button class="qz-opt" onclick="qzAnswer('+i+')">'+o.text+'</button>').join('')+
    '</div>'+
    '<div class="qz-explain" id="qzExplain"></div>'+
    '</div>';
  rubyify(box);
  // タイマー開始
  QZ_qStart = Date.now();
  if(QZ_qTimer) clearInterval(QZ_qTimer);
  QZ_qTimer = setInterval(()=>{
    const el = document.getElementById('qzTimer');
    if(el){ el.textContent = ((Date.now()-QZ_qStart)/1000).toFixed(1)+'秒'; }
  }, 100);
}

// --- 回答 ---
function qzAnswer(choiceIdx){
  if(QZ_answered) return;
  QZ_answered = true;
  if(QZ_qTimer){ clearInterval(QZ_qTimer); QZ_qTimer=null; }
  const q = QZ_today[QZ_idx];
  const sec = (Date.now()-QZ_qStart)/1000;
  const chosen = q._shuffled[choiceIdx];
  const isCorrect = chosen.correct;
  // 得点計算：正解=基礎7点＋スピードボーナス最大3点（5秒以内満点、以降減衰）
  let pts = 0;
  if(isCorrect){
    QZ_correct++;
    const base = 7;
    const speed = Math.max(0, 3 - Math.max(0, sec-2)*0.4); // 2秒までMAX、以降減る
    pts = Math.round((base + speed)*10)/10;
    QZ_score += pts;
  }
  QZ_results.push({correct:isCorrect, sec:Math.round(sec*10)/10, pts});
  // ボタンの色分け
  const btns = document.querySelectorAll('#qzOpts .qz-opt');
  q._shuffled.forEach((o,i)=>{
    if(o.correct) btns[i].classList.add('qz-correct');
    else if(i===choiceIdx) btns[i].classList.add('qz-wrong');
    btns[i].disabled = true;
  });
  // 解説表示
  const ex = document.getElementById('qzExplain');
  ex.innerHTML =
    '<div class="qz-ex-head '+(isCorrect?'ok':'ng')+'">'+(isCorrect?'⭕ せいかい！ +'+pts+'点':'❌ ざんねん…')+'</div>'+
    '<div class="qz-ex-body">'+q.e+'</div>'+
    '<button class="qz-btn qz-btn-next" onclick="qzNext()">'+(QZ_idx<9?'つぎの問題 ▶':'結果を見る 🎉')+'</button>';
  rubyify(ex);
}

// --- 次へ ---
function qzNext(){
  QZ_idx++;
  if(QZ_idx>=QZ_today.length){ qzFinish(); }
  else{ qzRenderQuestion(); }
}

// --- 結果 ---
function qzFinish(){
  const score = Math.round(QZ_score);
  const t = qzTitle(score);
  // 記録保存（本番のみ）
  const data = qzLoad();
  let streak = 0;
  if(!QZ_practice){
    const today = qzTodayStr();
    // 連続日数の更新
    streak = qzUpdateStreak(data, today);
    data.lastDate = today;
    data.lastResult = {score, correct:QZ_correct};
    // ベストスコア
    if(!data.best || score>data.best){ data.best = score; }
    // 総プレイ回数
    data.plays = (data.plays||0)+1;
    qzSave(data);
  }else{
    streak = qzStreakCount(data);
  }
  const box = document.getElementById('qzBody');
  box.innerHTML =
    '<div class="qz-start">'+
    '<div class="qz-fanfare">'+(score>=90?'🎊':score>=65?'✨':'🌱')+'</div>'+
    '<div class="qz-result-card" id="qzShareCard">'+
      '<div class="qz-rc-head">金沢まるっと10問クイズ</div>'+
      '<div class="qz-rc-date">'+qzTodayStr()+(QZ_practice?'（れんしゅう）':' の記録')+'</div>'+
      '<div class="qz-rc-emoji">'+t.icon+'</div>'+
      '<div class="qz-rc-score">'+score+'<span>点</span></div>'+
      '<div class="qz-rc-title">'+t.name+'</div>'+
      '<div class="qz-rc-detail">10問中 '+QZ_correct+'問せいかい</div>'+
      (streak>0&&!QZ_practice? '<div class="qz-rc-streak">🔥 '+streak+'日れんぞく</div>':'')+
    '</div>'+
    '<p class="qz-sub">'+t.sub+'</p>'+
    '<button class="qz-btn qz-btn-share" onclick="qzShare()">📤 スコアをシェアする</button>'+
    (!QZ_practice
      ? '<button class="qz-btn qz-btn-rank" onclick="qzOpenPost()">🏅 ランキングに投稿する</button>'
      : '')+
    '<button class="qz-btn qz-btn-rankview" onclick="qzViewRanking()">🏆 ランキングを見る</button>'+
    (QZ_practice
      ? '<button class="qz-btn qz-btn-ghost" onclick="qzStartGame(true)">もう一回あそぶ</button>'
      : '<button class="qz-btn qz-btn-ghost" onclick="qzStartGame(true)">もう一回あそぶ（記録は残りません）</button>')+
    '<p class="qz-note">'+(QZ_practice?'':'また明日、あたらしい10問が出るよ！')+'</p>'+
    '</div>';
  rubyify(box);
}

// --- 連続日数：更新 ---
function qzUpdateStreak(data, today){
  const last = data.lastDate;
  if(last===today){ return data.streak||1; } // 同日再記録
  // todayの前日を計算
  const y = new Date(today+'T00:00:00'); y.setDate(y.getDate()-1);
  const ys = y.getFullYear()+'-'+('0'+(y.getMonth()+1)).slice(-2)+'-'+('0'+y.getDate()).slice(-2);
  if(last===ys){ data.streak = (data.streak||0)+1; }
  else{ data.streak = 1; }
  return data.streak;
}
// --- 連続日数：表示用（今日/昨日やってれば有効） ---
function qzStreakCount(data){
  if(!data.lastDate || !data.streak) return 0;
  const today = qzTodayStr();
  const y = new Date(today+'T00:00:00'); y.setDate(y.getDate()-1);
  const ys = y.getFullYear()+'-'+('0'+(y.getMonth()+1)).slice(-2)+'-'+('0'+y.getDate()).slice(-2);
  if(data.lastDate===today || data.lastDate===ys) return data.streak;
  return 0; // 途切れた
}

// --- シェア ---
function qzShare(){
  const card = document.getElementById('qzShareCard');
  let scoreText = '';
  const sc = card ? card.querySelector('.qz-rc-score') : null;
  const ti = card ? card.querySelector('.qz-rc-title') : null;
  const score = sc ? sc.textContent.replace('点','') : '';
  const title = ti ? ti.textContent : '';
  const text = '【金沢まるっと10問クイズ】\n今日のスコアは '+score+'点！\n称号：'+title+'\n\nあなたも金沢のことどれくらい知ってる？\n#金沢まるっと #金沢クイズ';
  const url = location.href;
  if(navigator.share){
    navigator.share({title:'金沢まるっと10問クイズ', text:text, url:url}).catch(()=>{});
  }else{
    // クリップボードにコピー
    const full = text+'\n'+url;
    if(navigator.clipboard){
      navigator.clipboard.writeText(full).then(()=>{
        qzToast('コピーしたよ！SNSに貼りつけてね');
      }).catch(()=>{ qzShareFallback(full); });
    }else{ qzShareFallback(full); }
  }
}
function qzShareFallback(text){
  const ta=document.createElement('textarea'); ta.value=text; document.body.appendChild(ta);
  ta.select(); try{document.execCommand('copy'); qzToast('コピーしたよ！SNSに貼りつけてね');}catch(e){}
  document.body.removeChild(ta);
}
function qzToast(msg){
  let t=document.getElementById('qzToast');
  if(!t){ t=document.createElement('div'); t.id='qzToast'; t.className='qz-toast'; document.body.appendChild(t); }
  t.textContent=msg; t.classList.add('show');
  setTimeout(()=>t.classList.remove('show'), 2200);
}

