// ひらがな/カタカナ/全角英数を正規化してチェック
function qzNormalize(str){
  let s = str.toLowerCase();
  // 全角英数→半角
  s = s.replace(/[Ａ-Ｚａ-ｚ０-９]/g, c => String.fromCharCode(c.charCodeAt(0)-0xFEE0));
  // カタカナ→ひらがな
  s = s.replace(/[\u30a1-\u30f6]/g, c => String.fromCharCode(c.charCodeAt(0)-0x60));
  // 記号・空白除去（すり抜け防止）
  s = s.replace(/[\s・.,\-_*＊゛゜ー~〜｜|]/g,'');
  return s;
}
function qzCheckName(name){
  const raw = name.trim();
  if(raw.length===0) return {ok:false, msg:'名前を入れてね'};
  if([...raw].length>8) return {ok:false, msg:'名前は8文字までにしてね'};
  // 使える文字：日本語・英数字のみ（絵文字や記号の羅列を防ぐ）
  if(!/^[ぁ-んァ-ヶ一-龠々ー0-9A-Za-z]+$/.test(raw)){
    return {ok:false, msg:'ひらがな・カタカナ・かん字・アルファベット・数字が使えるよ'};
  }
  // NGワードチェック（正規化して部分一致）
  const norm = qzNormalize(raw);
  for(const ng of QZ_NG_PATTERNS){
    const nng = qzNormalize(ng);
    if(nng && norm.includes(nng)){
      return {ok:false, msg:'その名前はつかえないよ。ほかの名前にしてね'};
    }
  }
  return {ok:true, name:raw};
}

// --- ランキング保存/読み込み ---
const QZ_RANK_API = 'https://script.google.com/macros/s/AKfycbzdYm37-INScXlHoqjC2lDTVfaDsJxotD_ViGB-EehLfZ8FNIB0zu2kzlrX8JOfA5xX6w/exec';
// 全国ランキングを読む(GAS・GET)。通信失敗はnullを返す
function qzRankFetch(){
  return new Promise((resolve)=>{
    const cb = 'qzcb_' + Date.now() + '_' + Math.floor(Math.random()*1e6);
    let done = false;
    const s = document.createElement('script');
    const cleanup = ()=>{ try{ delete window[cb]; }catch(e){ window[cb]=undefined; } if(s.parentNode) s.parentNode.removeChild(s); };
    window[cb] = (data)=>{ if(done) return; done=true; cleanup(); resolve((data && data.ok && Array.isArray(data.list)) ? data.list : []); };
    s.onerror = ()=>{ if(done) return; done=true; cleanup(); resolve(null); };
    // 8秒で応答が無ければ通信失敗扱い
    setTimeout(()=>{ if(done) return; done=true; cleanup(); resolve(null); }, 8000);
    s.src = QZ_RANK_API + '?day=' + encodeURIComponent(qzTodayStr()) + '&callback=' + cb + '&t=' + Date.now();
    document.body.appendChild(s);
  });
}
// 全国ランキングに投稿(GAS・POST)。text/plainでCORSプリフライト回避
async function qzRankPost(entry){
  try{
    const res = await fetch(QZ_RANK_API, {
      method:'POST',
      headers:{'Content-Type':'text/plain;charset=utf-8'},
      body: JSON.stringify(entry)
    });
    const data = await res.json();
    return !!(data && data.ok);
  }catch(e){ return false; }
}

