// --- 名前を決めて投稿 ---
async function qzSubmitName(){
  const inp = document.getElementById('qzNameInput');
  const msg = document.getElementById('qzNameMsg');
  const check = qzCheckName(inp.value);
  if(!check.ok){
    msg.textContent = '⚠ ' + check.msg;
    msg.className = 'qz-name-msg err';
    return;
  }
  const score = Math.round(QZ_score);
  const entry = { name: check.name, score: score, correct: QZ_correct, day: qzTodayStr() };
  msg.textContent = '投稿中…';
  msg.className = 'qz-name-msg';
  const ok = await qzRankPost(entry);
  if(!ok){
    msg.textContent = '⚠ つうしんにしっぱいしたよ。もう一度ためしてね';
    msg.className = 'qz-name-msg err';
    return;
  }
  qzShowRanking({ name: entry.name, score: entry.score, day: entry.day });
}

