const KOHKA_DATA=[['長町',0,0,'香林坊・高岡町・片町・竪町・長町','武家屋敷跡・香林坊・片町を含む城下町の中心。','中央','<b>🏯 加賀藩士の武家屋敷が残るまち</b><br>長町（ながまち）は、加賀藩の中級・上級の武士が住んだ屋敷街です。今も黄土色の土塀と石畳の小路が残り、敵が一気に攻め込めないよう道をわざとクランク（かぎ型）に曲げるなど、城下町ならではの工夫が見られます。冬には土塀を雪から守る「こも掛け」が行われ、雪吊りとともに金沢の冬の風物詩になっています。<br><br><b>❓ 「長町」の名前、由来は2説</b><br>ひとつは、細長い町域だから「長町」という説。もうひとつは、加賀藩の最上級の家臣グループ「加賀八家（かがはっか）」のひとつ<b>長（ちょう）家</b>がこのあたりに住んでいたことから「長家の町→長町」になったという説です。どちらが正しいかは、はっきりしていません。<br><br><b>💧 金沢で最も古い用水・大野庄用水</b><br>長町を流れる<b>大野庄用水（おおのしょうようすい）</b>は、金沢で最も古い用水路。天正11年（1583年）に前田利家が金沢城に入ってまもなく開かれ、金沢城の改修工事では、宮腰（みやのこし＝今の金石）の港で陸あげした木材を運ぶ水路として使われました。武家屋敷の庭園にもこの水が引き込まれています。<br><br><b>🏡 野村家</b><br>武家屋敷跡の野村家は、前田利家の直臣・野村伝兵衛信貞（のむらでんべえのぶさだ）を初代とし、廃藩まで11代続いた名家。庭園はアメリカの庭園専門誌のランキングで日本3位に選ばれ、ミシュランの評価も受けています。'],['長土塀',0,0,'長町・長土塀・大和町・三社町','','中央'],['松ヶ枝',0,0,'青草町・尾山町・大手町(一部)・尾張町(一部)','','中央'],['芳斎',0,0,'玉川町・白銀町・本町・昭和町・六枚町・三社町','','中央'],['瓢箪',0,0,'彦三・横安江町・笠市町・瓢箪町','','中央'],['此花',0,0,'此花町・本町・堀川町・笠市町(一部)','','中央'],['味噌蔵町',0,0,'暁町・扇町・大手町・尾張町・兼六元町・兼六町・小将町','尾張町など城下の老舗商店街を含む。','中央','<b>🏪 尾張町（おわりちょう）—— 利家の故郷から来た商人のまち</b><br>この校下には、金沢経済の中心地だった<b>尾張町</b>があります。名前の由来は、藩祖・前田利家が金沢に入るとき、自身の生まれ故郷である<b>尾張・荒子（あらこ／今の名古屋市中川区）</b>から呼び寄せた御用商人たちを住まわせたことにちなみます。利家にとって故郷・尾張は「信頼の根源」でした。<br><br><b>💰 江戸時代の金沢経済の中枢</b><br>江戸期の尾張町は、米の売買を中心に70軒以上の店がならぶ、金沢いちばんの商人町でした。江戸と金沢を月に3回往復する飛脚「江戸三度（えどさんど）」の集荷所も置かれていました。今も創業100年をこえる老舗が並び、「オールド金沢」とも呼ばれる町並みが残っています。<br><br><b>🏯 金沢城と兼六園のお膝元</b><br>この校下には兼六町・兼六元町も含まれ、金沢城・兼六園のすぐそば。城の大手門・黒門を出るとまず武家の大手町があり、その先に尾張商人の町がひろがる——城下町の構造がそのまま地名に残っています。'],['材木',0,0,'暁町(一部)・尾張町(一部)','','中央'],['小立野',10946,5951,'石引・上野本町(丙)・笠舞(一部)','石川県立図書館（2022年移転）や金沢大学がある高台の文教地区。','東部・城南','<b>⛰ 金沢城が築かれた台地の先端</b><br>小立野（こだつの）は、犀川と浅野川という2つの川にはさまれた「小立野台地」の上にあります。この台地の先端に築かれたのが金沢城でした。城を建てるとき、戸室山（とむろやま）から切り出した石垣用の石（戸室石）を運んだ道は「いし曳（び）きの道」と呼ばれ、今の小立野通りにあたります。<br><br><b>🛕 前田家ゆかりの寺が集まる「小立野寺院群」</b><br>元和2年（1616年）ごろ、加賀藩3代・前田利常は、城下に散らばっていた寺社を、城の防備・戸籍の管理・宗教対策などのために3か所へ集めました。それが金沢三寺院群（小立野・卯辰山山麓・寺町）です。小立野には約40の寺社が集まり、いし曳きの道沿いに前田家ゆかりの寺が点在しています。<br><br><b>💐 珠姫（たまひめ）を供養する天徳院</b><br>なかでも<b>天徳院</b>は、3代利常が正室・珠姫を供養するために建てた寺です。珠姫は徳川秀忠の娘で、前田家と徳川家を結ぶため、わずか3歳で前田家に嫁ぎ、24歳の若さで亡くなりました。前田家の菩提寺・宝円寺（利家ゆかり）もこの地にあります。<br><br><b>📚 いまは学生街・文教のまち</b><br>明治以降、この一帯には学校が集まりました。今も金沢大学（医薬保健系）や金沢美術工芸大学などがあり、2022年（令和4年）には石川県立図書館が移転してきて、金沢を代表する文教地区になっています。'],['崎浦',0,0,'','','東部・城南'],['内川',825,509,'小原町','','東部・城南'],['犀川',5519,2813,'相合谷町・天池町・大平沢町・鴛原町・樫見町','','東部・城南'],['湯涌',780,402,'石黒町・板ヶ谷町・上山町・魚帰町・大菱池町・折谷町','湯涌温泉がある市東部の温泉地区。','東部・城南','<b>♨ 開湯1300年、加賀藩主の奥座敷</b><br>湯涌（ゆわく）温泉は、開湯が718年とされる山あいの温泉地。白鷺（しらさぎ）が傷を癒すのを見て湯が見つかったという言い伝えがあり、2018年には開湯1300年を祝いました。藩政期には加賀藩の歴代藩主が通う「湯治場（とうじば）」として栄え、「金沢の奥座敷」と呼ばれてきました。<br><br><b>🎨 竹久夢二の「ロマンの湯」</b><br>大正の詩人画家<b>竹久夢二（たけひさゆめじ）</b>は、1917年（大正6年）、恋人の笠井彦乃（かさいひこの）とこの湯涌で3週間をすごしました。その縁で「金沢湯涌夢二館」が建てられ、夢二の作品や生涯を伝えています。<br><br><b>🏮 アニメの聖地・湯涌ぼんぼり祭り</b><br>湯涌温泉は、2011年放送のアニメ「花咲くいろは」の舞台のモデルにもなりました。作中に登場する架空のお祭り「ぼんぼり祭り」を、地域の人たちが本物のお祭りとして実現し、毎年開催しています。物語がきっかけで生まれたお祭りに、今では全国からファンや家族連れが訪れる——歴史ある温泉地の、新しい物語です。'],['田上',4209,2112,'朝霧台・旭町・角間町・角間新町','','東部・城南','<b>🎓 金沢大学の門前町</b><br>田上（たがみ）は、金沢市南東部の丘陵地に広がる地区です。もとは田畑や山手ののどかな土地でしたが、1964年（昭和39年）から住宅団地の造成が始まり、田上新町などが生まれました。近くの角間（かくま）に金沢大学のメインキャンパスが移ってきてからは、その門前町として発展。学生でにぎわう杜の里（もりのさと）なども開発され、金沢の「学びのまち」の一角になっています。<br><br><b>💧 金沢を支えた辰巳用水</b><br>この一帯の南、犀川の上流には、金沢が誇る土木遺産<b>辰巳（たつみ）用水</b>の水源があります。辰巳用水は、1632年（寛永9年）、金沢城下を焼いた大火をきっかけに造られた用水路。犀川上流から城まで約11kmを、トンネル（隧道）を掘り、わずかな傾きで水を通す高度な技術で引きました。城のお堀や、のちに兼六園の池・噴水の水にも使われ、金沢の暮らしと防火を支えてきました。'],['東浅川',0,0,'朝加屋町・浅川町・打尾町・金川町','','東部・城南'],['俵',0,0,'小豆沢町','','東部・城南'],['医王山',476,220,'荒山町・奥新保町','市東部の山あいの地区。現行小学校区では最も人口が少ない（約476人）。','東部・城南','<b>🪨 金沢城の石垣を生んだ「戸室石」の里</b><br>医王山（いおうぜん）校下は、市の東部の山あいにある、人口が最も少ない校下です。でもこの一帯には、金沢の歴史を足もとから支えた大切なものがあります——<b>戸室石（とむろいし）</b>です。<br><br><b>🏯 金沢城の大半を積んだ石</b><br>金沢城の石垣は、その大半が、城の東約8kmにある戸室山・キゴ山あたりで採れる戸室石（安山岩）で積まれています。文禄元年（1592年）ごろの石垣づくりから使われ、兼六園の石橋などにも用いられました。赤みを帯びた「赤戸室」と青みを帯びた「青戸室」があり、青戸室のほうが緻密で堅いとされます。金沢城の石垣が赤と青のモザイクに見えるのは、この2種類の石のおかげです。<br><br><b>🛷 「石引町」の名前の由来</b><br>切り出した重い戸室石は、城まで人の力で運ばれました。その運搬路が「いし曳（び）きの道」と呼ばれ、小立野の<b>「石引町（いしびきまち）」</b>という地名の由来になっています。金沢城の石ひとつをたどるだけでも、山から城までの物語が見えてきます。'],['野町',0,0,'泉1丁目(一部)・泉野町3丁目(一部)・泉本町4丁目','にし茶屋街と、文豪・室生犀星ゆかりの地を含む犀川ぞいの地区。','東部・城南','<b>🎎 にし茶屋街</b><br>野町広小路のあたりに広がる<b>にし茶屋街</b>は、ひがし・主計町と並ぶ金沢三茶屋街のひとつ。出格子の美しい茶屋建築が残り、国の重要伝統的建造物群保存地区に選ばれています。3つの茶屋街のなかでは最も多い芸妓が所属するといわれ、日が落ちると軒先の看板に灯がともり、昼とは違った風情になります。<br><br><b>✒ 文豪・室生犀星（むろうさいせい）のふるさと</b><br>金沢三文豪のひとり室生犀星は、この犀川ぞいで育ちました。犀川の両岸には、犀星が好んで歩いたことにちなむ散策路「犀星のみち」があり、生家跡の近くには室生犀星記念館があります。「ふるさとは遠きにありて思ふもの」の詩で知られる作家です。<br><br><b>🥷 隣接する寺町台と忍者寺</b><br>すぐ近くの寺町台には、約70の寺社が集まる金沢三寺院群のひとつ「寺町寺院群」が広がります。なかでも<b>妙立寺（みょうりゅうじ）</b>は、加賀3代藩主・前田利常が1643年に建てたお寺で、外観は2階建てに見えますが実際は4階7層という複雑な造り。落とし穴の賽銭箱や隠し階段などの仕掛けから、のちに「忍者寺」と呼ばれるようになりました（実際に忍者がいたわけではありません）。徳川幕府との緊張のなか、砦としての役目も担ったと伝えられます。'],['弥生',0,0,'有松(一部)・泉(一部)・泉が丘・泉野町(一部)','','東部・城南','<b>🛕 金沢三寺院群で最大「寺町寺院群」</b><br>この校下から寺町にかけての一帯には、金沢三寺院群のなかで<b>最も規模の大きい「寺町（てらまち）寺院群」</b>が広がります。約70もの寺社が集まり、小立野・卯辰山と同じく、3代・前田利常が一向一揆への防衛策として犀川ぞいに寺を集めたものです。2012年（平成24年）、寺町・野町・弥生の各一部が国の重要伝統的建造物群保存地区に選ばれました。<br><br><b>🔔 残したい日本の音風景</b><br>毎週土曜の夕方には、寺々の梵鐘（ぼんしょう）が空に鳴りわたります。この音は「残したい日本の音風景100選」に選ばれ、あたりは「静音（しずね）の小径」とも呼ばれています。<br><br><b>⛰ 文豪も歩いたW坂</b><br>犀川から寺町台へ上る石伐坂（いしきりざか）は、その形から<b>「W坂」</b>と呼ばれます。作家・井上靖が学生時代の通学路にしたことで知られ、小説「北の海」にも登場します。天然記念物の大桜がある松月寺、室生犀星ゆかりの雨宝院、織田信長を祀る泉野菅原神社など、物語のある寺社が点在しています。'],['中村町',8060,4726,'','','東部・城南','<b>⛩ 鎮座1100年の中村神社</b><br>中村町（なかむらまち）は、犀川ぞいの地区。地名のもとになった<b>中村神社</b>は、2009年（平成21年）に鎮座1100年を迎えた古い神社です。<br><br>もともと中村は犀川の右岸にありましたが、城下町の拡張にともなって左岸の今の場所へ移され、そのときに神社も一緒に移ってきたと伝えられます。町の名前と神社の歴史が、金沢の城下町づくりの歩みを今に伝えています。'],['十一屋',6897,3670,'大桑(一部)・笠舞町(ナ)','','東部・城南'],['泉野',8324,3844,'泉野町・泉野出町(一部)','','東部・城南'],['長坂台',9212,4377,'泉野出町(一部)・円光寺1丁目・円光寺2丁目','','東部・城南'],['新竪町',0,0,'油車・池田町・柿木畠・茨木町・枝町・鱗町・片町1丁目(一部)','','東部・城南'],['菊川',0,0,'笠舞2丁目(一部)・笠舞3丁目(一部)・笠舞本町(一部)','','東部・城南'],['米丸',15632,7308,'入江町・入江3丁目','','南部'],['新神田',7559,3932,'糸田町・糸田・入江1丁目・入江2丁目','','南部'],['押野',9342,4303,'押野1〜3丁目','','南部'],['西南部',10148,4710,'','','南部'],['三和',9210,4414,'いなほ・上荒屋','','南部'],['三馬',13089,6495,'有松・泉本町(一部)・泉(一部)','','南部'],['米泉',6770,3262,'泉本町7丁目','','南部'],['富樫',9283,4705,'円光寺(一部)・円光寺本町・円光寺3丁目','','南部','<b>⚔ 前田家より前の加賀の支配者「富樫氏」</b><br>富樫（とがし）という地名は、前田家が来るずっと前、<b>室町時代に加賀国を治めた守護大名・富樫氏（とがしし）</b>にちなみます。富樫氏は平安時代後期からこの一帯「富樫郷（とがしごう）」に住み、朝廷の役職「加賀介（かがのすけ）」を代々つとめ、「富樫介（とがしのすけ）」とも呼ばれた名門でした。<br><br><b>🎭 歌舞伎「勧進帳」の富樫</b><br>安宅（あたか）の関で義経・弁慶を見逃す関守として、歌舞伎「勧進帳」や能「安宅」に登場する<b>富樫左衛門</b>は、この富樫氏の一族（富樫泰家）に比定されています。加賀の富樫氏は、それほど広く名を知られた一族でした。<br><br><b>🏔 「百姓の持ちたる国」の始まり</b><br>富樫氏の本拠地は、となりの野々市（ののいち）にありました。1488年（長享2年）、当主・富樫政親（まさちか）は加賀一向一揆（浄土真宗の門徒による一揆）に敗れ、高尾城で自害。以後、加賀は「百姓の持ちたる国」と呼ばれる、約100年の一向一揆の時代に入ります。この時代を終わらせて金沢に入ったのが前田利家でした。金沢南部には、京都をまねた山科・伏見などの地名も今に残ります。'],['伏見台',13665,6510,'円光寺町(ニ)','','南部'],['額・四十万',16528,7485,'大額町・大額1〜3丁目','市南部。「四十万（しじま）」は難読地名として知られる。','南部','<b>📖 難読地名「四十万（しじま）」の伝説</b><br>「四十万」と書いて「しじま」と読む、石川県を代表する難読地名です。その由来には、阿弥陀如来（あみだにょらい）が遠い百済（くだら／今の朝鮮半島）の国から来たとき、「四十万里（しじゅうまんり）もある遠いところから来た」と言ったという言い伝えがあります。1里は約4kmなので、40万里はとてつもない距離——それほど遠くから来た、という意味が地名になったと伝えられます。<br><br><b>🪨 「額（ぬか）」と石切りの歴史</b><br>「額」は「ぬか」と読みます。額谷（ぬかだに）では、藩政期から昭和のはじめにかけて石が切り出され、「額谷石（ぬかだんし）」と呼ばれて家の土台などに使われました。今も山あいに石切り場の跡が残っています。<br><br><b>⚔ 富樫氏ゆかりの地</b><br>額谷町の御廟谷（ごびょうだに）は、この地方をおさめた守護大名・富樫氏（→富樫校下）の代々の墓所と伝えられています。金沢南部の富樫・伏見台・扇台・額の一帯は、前田家より前の加賀の歴史が息づくエリアです。'],['扇台',7532,3808,'','','南部'],['馬場',0,0,'鴬町・卯辰町・主計町','金沢三茶屋街のうち、ひがし・主計町の2つを含む茶屋街の中心地。','北部','<b>🏮 主計町（かずえまち）</b><br>この校下にある主計町は、金沢を代表する茶屋街のひとつ。名前は、加賀藩の重臣<b>富田主計重家（とだかずえしげいえ）</b>の屋敷がこの一帯にあったことに由来します。富田主計は一万六百石を知行した人持組頭で、大坂の陣で戦功をあげましたが、1618年に24歳で亡くなりました。<br><br><b>📜 「かずえまち」が一度消えた話</b><br>茶屋街としては明治期に形づくられ、ひがし・にしと並ぶ金沢三茶屋街のひとつとして、浅野川の近くから「ながれ」とも呼ばれました。1970年（昭和45年）、住居表示の変更で町名が「尾張町2丁目」となり、いったん「主計町」は地図から消えます。しかし住民の要望により、<b>1999年（平成11年）に全国で初めて旧町名が復活</b>。これが全国に広がる旧町名復活運動の先がけとなりました。<br><br><b>🌸 名所</b><br>浅野川沿いの桜並木、久保市乙剣宮から続く「暗がり坂」、作家・五木寛之が2008年に名づけた「あかり坂」があります。隣接する下新町は文豪・泉鏡花の生まれた地。一帯は国の重要伝統的建造物群保存地区に選ばれています。<br><br><b>🏘 ひがし茶屋街</b><br>この校下には、金沢三茶屋街のなかで最も規模が大きく格式が高いとされた<b>ひがし茶屋街</b>もあります。文政3年（1820年）、加賀藩12代・前田斉広（なりなが）の時代に、城下に点在していた茶屋を藩公認で浅野川の東（ひがし）と犀川の西（にし）にまとめたのが始まりです。金沢城から見た方角から、当時は「東の廓（くるわ）」と呼ばれました。京都・祇園に次いで2例目の茶屋町の重要伝統的建造物群保存地区で、出格子の茶屋建築が今も連なります。<br><br><b>⛩ 卯辰山山麓寺院群と「徳川を欺いた」神社</b><br>この一帯には、金沢三寺院群の最後のひとつ<b>卯辰山山麓（うたつやまさんろく）寺院群</b>も広がります。約50の寺院が斜面に立ち並び、小立野・寺町と同じく、3代・前田利常が一向宗（浄土真宗）以外の寺を集めて整えたものです。<br><br>なかでも<b>宇多須（うたす）神社</b>には、加賀藩ならではの秘話があります。慶長4年（1599年）、金沢城の鬼門（北東）を守るため、藩祖・前田利家を祀ろうとしましたが、当時は徳川の世。前田家は徳川に遠慮して、利家を正面から神としてまつることができず、規模をおさえた「卯辰八幡宮」という形でひっそり祀りました。今はひがし茶屋街の芸妓が節分に舞を奉納する神社として知られています。'],['浅野町',6456,3351,'浅野本町・乙丸町','','北部','<b>🌊 浅野川と卯辰山のふもと</b><br>浅野町（あさのまち）は、金沢の二大河川のひとつ<b>浅野川</b>の下流ぞい、卯辰山（うたつやま）のふもとに広がる地区です。浅野川は、その穏やかな流れから「女川（おんながわ）」とも呼ばれ、荒々しい「男川」の犀川と対にされてきました。<br><br><b>⛰ 庶民のための山・卯辰山</b><br>近くの卯辰山には、加賀藩ならではの物語があります。慶応3年（1867年）、加賀藩14代・前田慶寧（よしやす）が、福沢諭吉の「西洋事情」に触発され、庶民のための養生所（病院）・作業所・芝居小屋などを整えようと卯辰山を開拓しました。大名の庭だった兼六園に対して、卯辰山は「庶民の憩いの場」として開かれた山で、大正3年（1914年）に卯辰山公園として開園しました。<br><br><b>🦁 加賀獅子の伝統</b><br>浅野川ぞいの町々には、金沢に伝わる勇壮な「加賀獅子（かがじし）」の獅子舞が受けつがれてきました。棒振りが大きな獅子と勇ましく舞うこの芸能は、金沢市の無形民俗文化財に指定され、百万石まつりや春秋の祭りで披露されています。'],['森山',7432,3719,'大樋町(一部)・春日町','','北部','<b>🍵 金沢を代表する焼き物「大樋焼」発祥の地</b><br>この校下の大樋町（おおひまち）は、350年つづく金沢の焼き物<b>大樋焼（おおひやき）</b>が生まれた場所です。寛文6年（1666年）、加賀藩5代・前田綱紀（つなのり）が、茶の湯を広めるため京都から裏千家4代・仙叟宗室（せんそうそうしつ）を茶道奉行として招きました。<br><br><b>🏺 土師長左衛門と大樋村の土</b><br>このとき同道した陶工<b>土師長左衛門（はじちょうざえもん）</b>が、大樋村（現・大樋町）で楽焼にあう土を見つけ、茶碗づくりを始めました。これが「大樋焼」の名の由来です。以後は前田家の御用窯（ごようがま）として栄え、初代から代々「大樋長左衛門」の名を受けつぎ、今も十一代まで続いています。<br><br><b>✋ ロクロを使わない手づくり</b><br>大樋焼は、ロクロを使わず手とヘラだけで一つひとつ成形し、京都の楽家から与えられた飴釉（あめぐすり）をかけるのが特徴。軽くてやわらかな口当たりで、茶の湯の器として愛されてきました。作品は大樋美術館（橋場町）で見ることができます。'],['小坂',12016,5517,'大樋町(一部)','','北部'],['千坂',11660,5350,'荒屋町・荒屋1丁目・今昭町・金市町','','北部'],['夕日寺',4596,1965,'','','北部'],['森本',10648,4757,'梅田町・大場町','市北東部。IC・幹線道路の結節点。','北部'],['湖南',0,0,'','','北部','<b>🌾 河北潟のほとりの村々</b><br>湖南（こなん）校下は、金沢市の北のはずれ、<b>河北潟（かほくがた）</b>の南に広がる田園地帯です。才田（さいだ）などの村々からなり、その名も「河北潟の南」に由来します。<br><br>河北潟は、かつて北陸最大級の潟湖（せきこ）でしたが、1964年（昭和39年）からの国営干拓事業で農地に変わりました。この河北潟は、金石の豪商・銭屋五兵衛（→金石町校下）が晩年に干拓を試みて罪に問われた、いわくのある潟でもあります。今は県内最大の湖沼として、渡り鳥の飛来地にもなっています。'],['薬師谷',0,0,'','','北部'],['三谷',0,0,'小池町','','北部','<b>🏞 医王山ふもとの里山</b><br>三谷（みたに）校下は、金沢市の東部、医王山（いおうぜん）のふもとに広がる里山の地区です。田畑と山あいの集落からなり、古くからの農村のたたずまいが残ります。<br><br>金沢の中心部から少し離れた、緑ゆたかなこうした校下が、金沢の水や自然を支えてきました。'],['花園',2466,1097,'浅丘町・今町・榎尾町','','北部'],['諸江',16936,8559,'磯部町・沖町・駅西新町(一部)','現行小学校区で最も人口が多い（諸江町）。市街地北西部。','西部'],['浅野川',5519,2273,'大河端町・大河端西・蚊爪町','','西部'],['鞍月',11455,5111,'大友町・大友1〜3丁目','','西部'],['粟崎',7201,3427,'粟崎町・粟崎浜町','内灘寄りの海沿い地区。','西部','<b>🎡 「北陸の宝塚」があったまち</b><br>粟崎（あわがさき）は、金沢の北西のはずれ、日本海と河北潟（かほくがた）にはさまれた砂丘のまちです。大正から昭和のはじめ、この対岸（今の内灘町側）に、<b>「北陸の宝塚」</b>と呼ばれた伝説の大遊園地<b>粟ヶ崎（あわがさき）遊園</b>がありました。<br><br><b>💰 材木王・平沢嘉太郎の夢</b><br>作ったのは、田井村（今の金沢市田井町）生まれで「北陸の材木王」と呼ばれた実業家<b>平沢嘉太郎（ひらさわかたろう）</b>。1925年（大正14年）、私財35万円（今の約40億円）を投じて開園しました。兼六園の2倍・約6万坪の敷地に、1000人収容※の大劇場、大浴場、動物園、野球場、スキー場まであったといいます。<br><br><b>🚋 浅電と「アワジェンヌ」</b><br>平沢は、宝塚をつくった阪急の小林一三にあこがれ、自ら敷いた浅野川電気鉄道（通称「浅電」＝今の北陸鉄道浅野川線）の終点に遊園をつくって客を呼びました。宝塚の「タカラジェンヌ」をもじった少女歌劇「アワジェンヌ」も人気に。しかし戦争の影響で、1943年（昭和18年）に閉園が告げられ、1944年に正式に閉鎖。今は本館の入口だけが残されています。'],['川北',0,0,'','','西部'],['大浦',7565,3138,'大浦町','','西部'],['長田町',5898,3381,'駅西本町(一部)','','西部'],['戸板',13215,6451,'出雲町・駅西本町(一部)','','西部'],['西',5524,2902,'駅西新町','','西部'],['二塚',0,0,'赤土町(一部)','','西部'],['安原',5401,2478,'打木町','','西部'],['大徳（木曳野含む）',26411,12139,'赤土町(一部)・畝田東・畝田中(一部)・駅西本町6丁目(一部)・畝田町・畝田西・桂町','市北西部。区画整理と住宅開発が進んだ地区。木曳野を含む。','西部'],['金石町',6798,3217,'金石相生町・金石北・金石西・金石東・金石本町・金石味噌屋町・金石通町','日本海に面した港町。北前船で栄えた歴史を持つ。','西部','<b>⚓ もとの名は「宮腰（みやのこし）」</b><br>金石は、藩政期には<b>宮腰（みやのこし）</b>と呼ばれた港町でした。<ruby>中世<rp>(</rp><rt>ちゅうせい</rt><rp>)</rp></ruby>から<ruby>湊<rp>(</rp><rt>みなと</rt><rp>)</rp></ruby>としてにぎわい、<ruby>江戸<rp>(</rp><rt>えど</rt><rp>)</rp></ruby><ruby>時代<rp>(</rp><rt>じだい</rt><rp>)</rp></ruby>には<ruby>北前船<rp>(</rp><rt>きたまえぶね</rt><rp>)</rp></ruby>の<ruby>寄港地<rp>(</rp><rt>きこうち</rt><rp>)</rp></ruby>に。<ruby>加賀藩<rp>(</rp><rt>かがはん</rt><rp>)</rp></ruby>の<ruby>外港<rp>(</rp><rt>がいこう</rt><rp>)</rp></ruby>（＝<ruby>海<rp>(</rp><rt>うみ</rt><rp>)</rp></ruby>の<ruby>玄関口<rp>(</rp><rt>げんかんぐち</rt><rp>)</rp></ruby>）として<ruby>重<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>んじられました。港から金沢城へは「金石街道」が一直線に敷かれ、その先の近江町市場へ海産物が運ばれました。<br><br><b>🚢 海の豪商・銭屋五兵衛（ぜにやごへえ）</b><br>江戸後期、この地を拠点に北前船で活躍したのが豪商<b>銭屋五兵衛</b>です。「海の百万石」と呼ばれるほどの交易で加賀藩の財政を支えましたが、晩年に手がけた河北潟（かほくがた）の干拓事業をめぐって罪に問われ、獄中で亡くなりました。今も金石本町に銭屋五兵衛記念館があり、その生涯と北前船の歴史を伝えています。<br><br><b>🤝 「金石」という名前の由来</b><br>隣の大野村とは、港の利権をめぐる対立が長く続きました。これを見かねた加賀藩が1866年（慶応2年）に両地区を結びつけ、<b>「固いこと金石（きんせき）の交わり」</b>（＝固い約束、という意味の言葉）にちなんで「金石（かないわ）」と名づけたと伝えられます。対立していた二つの町の和解を願った町名です。1943年（昭和18年）に金沢市へ編入されました。'],['大野町',2016,882,'大野町・金石北3丁目(一部)','醤油醸造で知られる港町。「大野醤油」の産地。','西部','<b>🛢 醤油の五大産地のひとつ</b><br>大野は、千葉の野田・銚子、兵庫の龍野、香川の小豆島と並ぶ、<b>醤油の五大産地</b>のひとつに数えられてきた港町です。全盛期には60軒以上の醤油醸造業者がありました。<br><br><b>📜 はじまりは約400年前</b><br>大野の醤油づくりは、元和年間（1615〜1624年）に、大野の町人<b>直江屋伊兵衛（なおえやいへえ）</b>が、加賀藩3代藩主・前田利常の命を受けて紀州湯浅（きしゅうゆあさ／今の和歌山県）の醸造法を学び、広めたことに始まると伝えられます。以来、加賀藩の保護のもとで加賀藩の特産のひとつになりました。<br><br><b>🌊 なぜ大野で発展したのか</b><br>①城下町・金沢という大きな消費地が近いこと、②北前船の寄港地で麦・大豆・能登の塩など原料が手に入りやすかったこと、③白山（はくさん）の豊かな伏流水と湿潤な気候が醸造に向いていたこと。この好条件が重なりました。大野の少し甘めな「うまくち醤油」は、今も加賀料理に欠かせない味です。<br><br><b>🏛 いまの大野</b><br>醤油蔵や町家が連なる町並みは、金沢市の「こまちなみ保存区域」「文化的景観区域」に指定され、2017年（平成29年）には文化庁の日本遺産にも認定されました。蔵をリノベーションしたカフェやギャラリーも生まれています。']];
