(window.initKohka=function(){
  const sel=document.getElementById('kohkaSelect');
  if(!sel)return;
  // 地区ごとにグループ化して並べる
  const areas=['中央','東部・城南','南部','北部','西部'];
  areas.forEach(area=>{
    const list=KOHKA_DATA.filter(k=>k[5]===area);
    if(!list.length)return;
    const og=document.createElement('optgroup');
    og.label=area;
    list.forEach(k=>{
      const o=document.createElement('option');
      o.value=k[0];
      const ym=KOHKA_YOMI[k[0]]?'（'+KOHKA_YOMI[k[0]]+'）':'';
      o.textContent=k[0]+ym+(k[1]>0?'　'+k[1].toLocaleString()+'人':'');
      og.appendChild(o);
    });
    sel.appendChild(og);
  });
})();
