  // ===== ディープリンク：URLの#idでカードを直接開く =====
  function openFromHash(){
    const raw=decodeURIComponent(location.hash.replace('#',''));
    if(!raw)return;
    // #カードID  または  #カードID-N (Nはタブ番号 1始まり)
    let id=raw, tabNo=0;
    const mt=raw.match(/^(.+)-(\d+)$/);
    if(mt && document.getElementById(mt[1])){ id=mt[1]; tabNo=parseInt(mt[2],10); }
    const p=document.getElementById(id);
    if(p && p.classList.contains('cat-panel')){
      if(!p.classList.contains('on')) openCat(id);
      if(tabNo>0){
        setTimeout(function(){
          const tabs=document.querySelectorAll('#'+id+' .rn-tab');
          if(tabs[tabNo-1]) tabs[tabNo-1].click();
        }, 450);
      }
    }
  }
  // タブ(rn-tab)を押したらURLを #カードID-N に更新(シェア用・Nはそのカードのタブ順)
  document.addEventListener('click', function(e){
    const btn=e.target.closest && e.target.closest('.rn-tab');
    if(!btn) return;
    const card=btn.closest('.cat-panel');
    if(!card || !card.id) return;
    const tabs=[].slice.call(card.querySelectorAll('.rn-tab'));
    const idx=tabs.indexOf(btn);
    if(idx>=0){ try{ history.replaceState(null,'','#'+card.id+'-'+(idx+1)); }catch(_){}}
  }, true);
  window.addEventListener('hashchange',openFromHash);
  // 初期ロード（描画完了後に開く。アニメ用IntersectionObserverより後）
  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',()=>setTimeout(openFromHash,150));
  }else{
    setTimeout(openFromHash,150);
  }


