    const def=(typeof TERMDIC!=='undefined')?TERMDIC[word]:null; if(!def)return;
    pop.innerHTML='<button class="tp-x" onclick="this.parentNode.style.display=\'none\'">✕</button><b>'+word+'</b><br>'+def;
