  var lv=0; for(var j=0;j<52;j++){ if(cum>=cumNeed[j]) lv=j+1; }
  if(done>lv) done=lv;
  var km=0; D.schools.forEach(function(s){ if(s.lv<=done) km+=s.rt; });
  var el=function(id){return root.querySelector('#'+id);};
  el('rq-lv').textContent=lv; el('rq-done').textContent=done; el('rq-cum').textContent=cum.toLocaleString(); el('rq-km').textContent=km.toFixed(1);
  var pct=Math.min(100,cum/TOTAL*100);
